        data: {"result": {"minY": 1000.0, "minX": 0.0, "maxY": 1000.0, "series": [{"data": [[0.0, 1000.0]], "isOverall": false, "label": "SeleccionTarifaYCantidad", "isController": false}, {"data": [[0.0, 1000.0]], "isOverall": false, "label": "Pago", "isController": false}, {"data": [[0.0, 1000.0]], "isOverall": false, "label": "Tarifas", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 4.9E-324, "title": "Response Time Distribution"}},
